from __future__ import annotations
from typing import Sequence

def sampled_energy(kappa: float, speed: float, weights: Sequence[float], dy: Sequence[float], dz: Sequence[float]) -> float:
    if not (len(weights) == len(dy) == len(dz)):
        raise ValueError("array lengths differ")
    return -kappa * speed**2 * sum(w*(gy**2+gz**2) for w, gy, gz in zip(weights,dy,dz))

